func TestBytesNPromotion(t *testing.T) {
	// With no decimals to show, the boundary is the same as for Bytes.
	boundaries := []struct {
		stay, promote, unit uint64
		from, to            string
	}{
		{999_499, 999_500, MByte, "kB", "MB"},
		{999_499_999, 999_500_000, GByte, "MB", "GB"},
		{999_499_999_999, 999_500_000_000, TByte, "GB", "TB"},
		{999_499_999_999_999, 999_500_000_000_000, PByte, "TB", "PB"},
		{999_500_000_000_000_000 - 65, 999_500_000_000_000_000, EByte, "PB", "EB"},
	}
	ones := map[int]string{-1: "1", 0: "1", 1: "1", 2: "1.0", 3: "1.00"}
	for n, one := range ones {
		for _, b := range boundaries {
			name := fmt.Sprintf("bytesN(%d, %d)", b.promote, n)
			testList{
				{name, BytesN(b.stay, n), "999 " + b.from},
				{name, BytesN(b.promote, n), one + " " + b.to},
				{name, BytesN(b.promote, n), BytesN(b.unit, n)},
			}.validate(t)
		}
	}

	testList{
		{"bytesN(1MB - 1, 3)", BytesN(999_999, 3), "1.00 MB"},
		{"bytesN(1MB - 1, 0)", BytesN(999_999, 0), BytesN(1_000_000, 0)},

		// More digits move the boundary closer to the next unit.
		{"bytesN(999949, 4)", BytesN(999_949, 4), "999.9 kB"},
		{"bytesN(999950, 4)", BytesN(999_950, 4), "1.000 MB"},
		{"bytesN(999994, 5)", BytesN(999_994, 5), "999.99 kB"},
		{"bytesN(999995, 5)", BytesN(999_995, 5), "1.0000 MB"},
		{"bytesN(999999, 6)", BytesN(999_999, 6), "999.999 kB"},
		{"bytesN(1MB, 6)", BytesN(1_000_000, 6), "1.00000 MB"},
		{"bytesN(999999499, 6)", BytesN(999_999_499, 6), "999.999 MB"},
		{"bytesN(999999500, 6)", BytesN(999_999_500, 6), "1.00000 GB"},

		// Too many digits for a float64: the rounding overflows, which must
		// not be mistaken for a carry to the next unit.
		{"bytesN(500kB, 309)", BytesN(500_000, 309), "+Inf kB"},

		{"ibytesN(1MiB - 1, 3)", IBytesN(1_048_575, 3), "1.00 MiB"},
		{"ibytesN(1023.5KiB - 1, 4)", IBytesN(1023.5*KiByte-1, 4), "1023 KiB"},
		{"ibytesN(1023.5KiB, 4)", IBytesN(1023.5*KiByte, 4), "1.000 MiB"},
		{"ibytesN(1023.95KiB, 5)", IBytesN(1_048_525, 5), "1024.0 KiB"},
		{"ibytesN(1MiB - 1, 5)", IBytesN(1_048_575, 5), "1.0000 MiB"},
	}.validate(t)
}

// checkParsedOutput verifies that out, the formatting of in, shows a number
// below base unless its unit is the last one, and that parsed, the value read
// back from it, is within one unit of its last printed digit.
func checkParsedOutput(t *testing.T, in *big.Int, out string, parsed *big.Int, base float64, last string) {
	t.Helper()
	num, unit, ok := strings.Cut(out, " ")
	if !ok {
		t.Errorf("%v: malformed output %q", in, out)
		return
	}
	v, err := strconv.ParseFloat(num, 64)
	if err != nil {
		t.Errorf("%v: malformed output %q: %v", in, out, err)
		return
	}
	if v >= base && unit != last {
		t.Errorf("%v: %q should have moved to the next unit", in, out)
	}

	one, err := ParseBigBytes("1 " + unit)
	if err != nil {
		t.Errorf("%v: unknown unit in %q: %v", in, out, err)
		return
	}
	digit := new(big.Rat).SetInt(one)
	if _, frac, ok := strings.Cut(num, "."); ok {
		digit.Quo(digit, new(big.Rat).SetInt(new(big.Int).Exp(ten, big.NewInt(int64(len(frac))), nil)))
	}
	diff := new(big.Rat).SetInt(new(big.Int).Sub(parsed, in))
	if diff.Abs(diff).Cmp(digit) > 0 {
		t.Errorf("%v: %q reads back as %v, more than %v away", in, out, parsed, digit.FloatString(1))
	}
}

// byteSizeSamples returns inputs around every boundary between units, around
// the points where the rounding carries to the next unit, and spread over the
// whole range up to limit.
func byteSizeSamples(limit *big.Int) []*big.Int {
	var samples []*big.Int
	add := func(s *big.Int) {
		if s.Sign() >= 0 && s.Cmp(limit) <= 0 {
			samples = append(samples, s)
		}
	}
	for _, base := range []int64{1000, 1024} {
		b := big.NewInt(base)
		for u := big.NewInt(1); u.Cmp(limit) <= 0; u = new(big.Int).Mul(u, b) {
			// One unit, and half a unit below it in the next smaller unit.
			half := new(big.Int).Div(u, big.NewInt(2*base))
			for _, c := range []*big.Int{u, new(big.Int).Sub(u, half)} {
				for d := int64(-130); d <= 130; d++ {
					add(new(big.Int).Add(c, big.NewInt(d)))
				}
			}
		}
	}
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		add(new(big.Int).Rsh(new(big.Int).Rand(r, limit), uint(r.Intn(limit.BitLen()))))
	}
	return samples
}

func TestBytesOutputsParseBack(t *testing.T) {
	limit := new(big.Int).SetUint64(1<<64 - 1)
	for _, s := range byteSizeSamples(limit) {
		u := s.Uint64()
		for _, c := range []struct {
			out, last string
			base      float64
		}{
			{Bytes(u), "EB", 1000},
			{IBytes(u), "EiB", 1024},
			{BytesN(u, 0), "EB", 1000},
			{BytesN(u, 1), "EB", 1000},
			{BytesN(u, 2), "EB", 1000},
			{BytesN(u, 3), "EB", 1000},
			{BytesN(u, 4), "EB", 1000},
			{BytesN(u, 6), "EB", 1000},
		} {
			parsed, err := ParseBytes(c.out)
			if err != nil {
				t.Errorf("%d: couldn't parse %q: %v", u, c.out, err)
				continue
			}
			checkParsedOutput(t, s, c.out, new(big.Int).SetUint64(parsed), c.base, c.last)
		}
	}
}

