new_tests='''// Every boundary a Big function can reach: the largest input that stays in its
// unit and the smallest one that is promoted, which is halfway to the next whole
// number at the top of the unit.
func TestBigBytesPromotion(t *testing.T) {
	tests := []struct {
		name  string
		f     func(*big.Int) string
		top   string
		sizes []string
		units []*big.Int
		twice int64 // twice the number at which the rounding reaches the base
	}{
		{
			"BigBytes", BigBytes, "999",
			[]string{"kB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB", "RB", "QB"},
			[]*big.Int{BigKByte, BigMByte, BigGByte, BigTByte, BigPByte, BigEByte, BigZByte, BigYByte, BigRByte, BigQByte},
			1999,
		},
		{
			"BigIBytes", BigIBytes, "1023",
			[]string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB", "RiB", "QiB"},
			[]*big.Int{BigKiByte, BigMiByte, BigGiByte, BigTiByte, BigPiByte, BigEiByte, BigZiByte, BigYiByte, BigRiByte, BigQiByte},
			2047,
		},
	}
	for _, tt := range tests {
		for i := 0; i < len(tt.units)-1; i++ {
			promote := new(big.Int).Mul(tt.units[i], big.NewInt(tt.twice))
			promote.Rsh(promote, 1)
			stay := new(big.Int).Sub(promote, BigByte)
			almost := new(big.Int).Sub(tt.units[i+1], BigByte)

			testList{
				{tt.name + " stay", tt.f(stay), tt.top + " " + tt.sizes[i]},
				{tt.name + " promote", tt.f(promote), "1.0 " + tt.sizes[i+1]},
				{tt.name + " one below", tt.f(almost), "1.0 " + tt.sizes[i+1]},
				{tt.name + " one", tt.f(tt.units[i+1]), "1.0 " + tt.sizes[i+1]},
			}.validate(t)
		}
	}

	testList{
		{"BigBytes(1GB - 1)", BigBytes(big.NewInt(GByte - 1)), "1.0 GB"},
		{"BigIBytes(1GiB - 1)", BigIBytes(big.NewInt(GiByte - 1)), "1.0 GiB"},

		// Bytes are never rounded, so this boundary has no promoted input.
		{"bbyte(999)", bbyte(999), "999 B"},
		{"bbyte(1000)", bbyte(1000), "1.0 kB"},
		{"bibyte(1023)", bibyte(1023), "1023 B"},
		{"bibyte(1024)", bibyte(1024), "1.0 KiB"},
	}.validate(t)
}

func TestBigBytesUnchanged(t *testing.T) {
	testList{
		{"bbyte(999499)", bbyte(999_499), "999 kB"},
		{"bibyte(1000KiB)", bibyte(1000 * 1024), "1000 KiB"},
		{"bibyte(1023KiB)", bibyte(1023 * 1024), "1023 KiB"},
		{"bibyte(999.5KiB)", bibyte(999.5 * KiByte), "1000 KiB"},
		// Carrying to 10.0 in the "%.1f" range is not a carry to the base.
		{"bbyte(9999)", bbyte(9999), "10.0 kB"},
		{"bibyte(10239)", bibyte(10239), "10.0 KiB"},
	}.validate(t)

	for s := uint64(0); s < 10; s++ {
		exp := fmt.Sprintf("%d B", s)
		testList{
			{"bbyte", bbyte(s), exp},
			{"bibyte", bibyte(s), exp},
		}.validate(t)
	}
}

// There is no unit after QB and QiB, so their number can reach the base.
func TestBigBytesLastUnit(t *testing.T) {
	mul := func(u *big.Int, n int64) *big.Int {
		return new(big.Int).Mul(u, big.NewInt(n))
	}
	half := func(u *big.Int, twice int64) *big.Int {
		return new(big.Int).Rsh(mul(u, twice), 1)
	}
	testList{
		{"999 QB", BigBytes(mul(BigQByte, 999)), "999 QB"},
		{"999.5 QB - 1", BigBytes(new(big.Int).Sub(half(BigQByte, 1999), BigByte)), "999 QB"},
		{"999.5 QB", BigBytes(half(BigQByte, 1999)), "1000 QB"},
		{"1000 QB - 1", BigBytes(new(big.Int).Sub(mul(BigQByte, 1000), BigByte)), "1000 QB"},
		{"1000 QB", BigBytes(mul(BigQByte, 1000)), "1000 QB"},
		{"12345 QB", BigBytes(mul(BigQByte, 12345)), "12345 QB"},

		{"1023 QiB", BigIBytes(mul(BigQiByte, 1023)), "1023 QiB"},
		{"1023.5 QiB - 1", BigIBytes(new(big.Int).Sub(half(BigQiByte, 2047), BigByte)), "1023 QiB"},
		{"1023.5 QiB", BigIBytes(half(BigQiByte, 2047)), "1024 QiB"},
		{"1024 QiB - 1", BigIBytes(new(big.Int).Sub(mul(BigQiByte, 1024), BigByte)), "1024 QiB"},
		{"1024 QiB", BigIBytes(mul(BigQiByte, 1024)), "1024 QiB"},
		{"12345 QiB", BigIBytes(mul(BigQiByte, 12345)), "12345 QiB"},
	}.validate(t)
}

func TestBigBytesDoesNotModifyInput(t *testing.T) {
	for _, in := range []int64{0, 9, 999, 999_499, 999_500, 999_999, MiByte - 1, GiByte - 1, GByte} {
		for name, f := range map[string]func(*big.Int) string{"BigBytes": BigBytes, "BigIBytes": BigIBytes} {
			s := big.NewInt(in)
			f(s)
			if s.Int64() != in {
				t.Errorf("%s changed its input from %d to %v", name, in, s)
			}
		}
	}
}

func TestBigBytesOutputsParseBack(t *testing.T) {
	limit := new(big.Int).Mul(BigQByte, big.NewInt(2000))
	for _, s := range byteSizeSamples(limit) {
		before := new(big.Int).Set(s)
		for _, c := range []struct {
			out, last string
			base      float64
		}{
			{BigBytes(s), "QB", 1000},
			{BigIBytes(s), "QiB", 1024},
		} {
			parsed, err := ParseBigBytes(c.out)
			if err != nil {
				t.Errorf("%v: couldn't parse %q: %v", s, c.out, err)
				continue
			}
			checkParsedOutput(t, s, c.out, parsed, c.base, c.last)
		}
		if s.Cmp(before) != 0 {
			t.Errorf("input changed from %v to %v", before, s)
		}
	}
}

