package main

import (
	"fmt"
	"math/big"
	"math/rand"
	"strconv"
	"strings"

	n "github.com/dustin/go-humanize"
	o "oldh"
)

var total, changed, bad int
var examples = map[string]string{}

// a change is legal only if the old number reached base with a larger unit available, and new == f(one unit).
func check(name, in, ov, nv string, base float64, order []string, one func(next string) string) {
	total++
	if ov == nv {
		f := strings.Fields(ov)
		v, err := strconv.ParseFloat(f[0], 64)
		if err == nil && v >= base && f[1] != order[len(order)-1] {
			bad++
			fmt.Println("NOT PROMOTED", name, in, ov)
		}
		return
	}
	changed++
	f := strings.Fields(ov)
	v, _ := strconv.ParseFloat(f[0], 64)
	idx := -1
	for i, u := range order {
		if u == f[1] {
			idx = i
		}
	}
	if v < base || idx == len(order)-1 || idx < 0 || nv != one(order[idx+1]) {
		bad++
		fmt.Println("ILLEGAL", name, in, ov, "->", nv)
	}
}

func main() {
	si := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
	iec := []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	bsi := append(append([]string{}, si...), "ZB", "YB", "RB", "QB")
	biec := append(append([]string{}, iec...), "ZiB", "YiB", "RiB", "QiB")
	pow := func(order []string, base uint64, u string) uint64 {
		p := uint64(1)
		for _, x := range order {
			if x == u {
				return p
			}
			p *= base
		}
		panic(u)
	}
	u64 := func(s uint64) {
		in := fmt.Sprint(s)
		check("Bytes", in, o.Bytes(s), n.Bytes(s), 1000, si, func(u string) string { return n.Bytes(pow(si, 1000, u)) })
		check("IBytes", in, o.IBytes(s), n.IBytes(s), 1024, iec, func(u string) string { return n.IBytes(pow(iec, 1024, u)) })
		for k := -1; k <= 8; k++ {
			k := k
			check(fmt.Sprintf("BytesN%d", k), in, o.BytesN(s, k), n.BytesN(s, k), 1000, si, func(u string) string { return n.BytesN(pow(si, 1000, u), k) })
			check(fmt.Sprintf("IBytesN%d", k), in, o.IBytesN(s, k), n.IBytesN(s, k), 1024, iec, func(u string) string { return n.IBytesN(pow(iec, 1024, u), k) })
		}
	}
	bigf := func(s *big.Int) {
		in := s.String()
		check("BigBytes", in, o.BigBytes(s), n.BigBytes(s), 1000, bsi, func(u string) string {
			p, _ := n.ParseBigBytes("1 " + u)
			return n.BigBytes(p)
		})
		check("BigIBytes", in, o.BigIBytes(s), n.BigIBytes(s), 1024, biec, func(u string) string {
			p, _ := n.ParseBigBytes("1 " + u)
			return n.BigIBytes(p)
		})
	}
	for s := uint64(0); s < 3_000_000; s++ {
		u64(s)
		bigf(new(big.Int).SetUint64(s))
	}
	r := rand.New(rand.NewSource(7))
	for i := 0; i < 3_000_000; i++ {
		s := r.Uint64() >> uint(r.Intn(64))
		u64(s)
		bigf(new(big.Int).SetUint64(s))
	}
	// around boundaries incl. Big range
	lim := new(big.Int).Exp(big.NewInt(10), big.NewInt(34), nil)
	for _, base := range []int64{1000, 1024} {
		for p := big.NewInt(base); p.Cmp(lim) < 0; p = new(big.Int).Mul(p, big.NewInt(base)) {
			for _, c := range []*big.Int{p, new(big.Int).Sub(p, new(big.Int).Div(p, big.NewInt(2*base)))} {
				for d := int64(-2000); d <= 2000; d++ {
					s := new(big.Int).Add(c, big.NewInt(d))
					bigf(s)
					if s.IsUint64() {
						u64(s.Uint64())
					}
				}
			}
		}
	}
	fmt.Println("comparisons", total, "changed", changed, "bad", bad)
}
